import{_ as a,o as n,c as e,a2 as s}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"Endpoints","description":"","frontmatter":{},"headers":[],"relativePath":"ja/concepts/endpoints.md","filePath":"ja/concepts/endpoints.md","lastUpdated":1784903584000}'),o={name:"ja/concepts/endpoints.md"};function d(p,t,i,r,c,l){return n(),e("div",null,[...t[0]||(t[0]=[s(`<h1 id="endpoints" tabindex="-1">Endpoints <a class="header-anchor" href="#endpoints" aria-label="Permalink to &quot;Endpoints&quot;">​</a></h1><p>エンドポイントは、呼び出し可能な特定の HTTP メソッド + パスです（例：<code>GET /api/users/{id}</code>）。エンドポイントは、LLM が発見、調査、呼び出しする実際の API 操作です。</p><h2 id="構造" tabindex="-1">構造 <a class="header-anchor" href="#構造" aria-label="Permalink to &quot;構造&quot;">​</a></h2><p>各エンドポイントには以下が含まれます：</p><ul><li><strong>HTTP メソッド</strong>: GET、POST、PUT、PATCH、DELETE、HEAD、OPTIONS</li><li><strong>パス</strong>: <code>/api/v1/users/{id}</code></li><li><strong>サマリー</strong>: エンドポイントの機能の短い説明 — LLM が一目で目的を理解するのに非常に便利</li><li><strong>説明</strong>: エンドポイントの動作、パラメーター、ユースケースの詳細な説明</li><li><strong>パラメーター</strong>: パス、クエリ、ヘッダー、Cookie</li><li><strong>リクエストボディ</strong>: POST/PUT/PATCH 用</li><li><strong>レスポンス</strong>: ステータスコードとレスポンススキーマ</li></ul><p><code>summary</code> と <code>description</code> フィールドは OpenAPI/Swagger/Postman ファイルから取得されます。これらは LLM がエンドポイントの機能を理解する主要な手段です。適切に書かれたサマリーは、エンドポイントの発見をより効果的にします。</p><h2 id="endpoint-用-mcp-ツール" tabindex="-1">Endpoint 用 MCP ツール <a class="header-anchor" href="#endpoint-用-mcp-ツール" aria-label="Permalink to &quot;Endpoint 用 MCP ツール&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ツール</th><th>説明</th></tr></thead><tbody><tr><td><code>endpoint_by_spec</code></td><td>spec 内のすべてのエンドポイント</td></tr><tr><td><code>endpoint_by_collection</code></td><td>collection 内のエンドポイント</td></tr><tr><td><code>endpoint_by_tag</code></td><td>タグ内のエンドポイント</td></tr><tr><td><code>endpoint_by_id</code></td><td>クイックエンドポイントサマリー</td></tr><tr><td><code>inspect</code></td><td>完全なエンドポイント詳細（スキーマ、パラメーター）</td></tr><tr><td><code>invoke</code></td><td>エンドポイントの呼び出し</td></tr><tr><td><code>search</code></td><td>テキストでエンドポイントを検索</td></tr></tbody></table><h2 id="非推奨のエンドポイント" tabindex="-1">非推奨のエンドポイント <a class="header-anchor" href="#非推奨のエンドポイント" aria-label="Permalink to &quot;非推奨のエンドポイント&quot;">​</a></h2><p>spec で <code>deprecated</code> とマークされたエンドポイントは、調査時に通知とともに表示されます。</p><h2 id="設定" tabindex="-1">設定 <a class="header-anchor" href="#設定" aria-label="Permalink to &quot;設定&quot;">​</a></h2><p>エンドポイントは swag2mcp の観点からは<strong>読み取り専用</strong>です。エンドポイント用の YAML 設定はありません — <code>swag2mcp.yaml</code> でエンドポイントを追加、削除、名前変更、変更することはできません。</p><p>エンドポイントを変更するには（新しいものの追加、サマリーの更新、パラメーターの変更、非推奨のマーク）、元の OpenAPI/Swagger/Postman ファイルを編集し、<code>swag2mcp update</code> を実行して再解析と再インデックス化を行います。</p><h2 id="例" tabindex="-1">例 <a class="header-anchor" href="#例" aria-label="Permalink to &quot;例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Query: &quot;Show details for GET /pet/{petId}&quot;</span></span>
<span class="line"><span>→ inspect(endpointId: &quot;abc123...&quot;)</span></span>
<span class="line"><span>→ Result:</span></span>
<span class="line"><span>  GET /pet/{petId}</span></span>
<span class="line"><span>  Summary: Find pet by ID</span></span>
<span class="line"><span>  Description: Returns a single pet by its ID</span></span>
<span class="line"><span>  Parameters:</span></span>
<span class="line"><span>    - petId (path, integer, required)</span></span>
<span class="line"><span>  Responses:</span></span>
<span class="line"><span>    - 200: Pet object</span></span>
<span class="line"><span>    - 400: Error</span></span>
<span class="line"><span>    - 404: Not found</span></span></code></pre></div>`,15)])])}const g=a(o,[["render",d]]);export{u as __pageData,g as default};
